<template><div class="page"><header class="head"><div><span class="eyebrow">RELEASE HEALTH</span><h1>版本变化</h1><p>选择项目，查看相邻版本的异常变化明细。</p></div><div class="actions"><el-select v-model="project" clearable filterable placeholder="全部项目"><el-option v-for="item in projects" :key="item" :label="item" :value="item" /></el-select><el-button :icon="Refresh" :loading="loading" @click="load">刷新</el-button></div></header><el-alert v-if="error" :title="error" type="warning" show-icon :closable="false" class="mb"/><section class="panel"><div v-if="filtered.length" class="list"><button v-for="row in filtered" :key="`${row.project}-${row.currentTaskId}`" class="row" @click="open(row)"><span><strong>{{row.project}}</strong><small>{{row.baselineVersion}} <el-icon><ArrowRight/></el-icon> {{row.currentVersion}}</small></span><b :class="{hot:row.attention}">{{row.newCount+row.increasedCount}} 项新增 / 增多</b><i>查看明细 <el-icon><ArrowRight/></el-icon></i></button></div><el-empty v-else description="每个项目至少需要两个不同版本的已完成任务" :image-size="80"/></section><el-dialog v-model="dialog" title="版本对比明细" width="min(820px, calc(100vw - 24px))"><div v-if="selected" class="details"><div class="summary"><span><b>{{selected.newCount}}</b>新增</span><span><b>{{selected.increasedCount}}</b>增多</span><span><b>{{selected.persistentCount}}</b>持续</span><span><b>{{selected.decreasedCount}}</b>减少</span></div><section v-for="group in groups" v-show="selected.details[group.key]?.length" :key="group.key"><strong>{{group.label}}（{{selected.details[group.key].length}}）</strong><button v-for="(item,index) in selected.details[group.key]" :key="`${item.file_path}-${index}`" @click="router.push({name:'TaskDetail',params:{taskId:selected.currentTaskId}})"><span>{{item.rule_name||item.matched_text||'未命名规则'}}</span><small>{{item.file_path||'未记录文件'}}</small></button></section></div></el-dialog></div></template>
<script setup>
import { computed, onMounted, ref } from 'vue';import { useRouter } from 'vue-router';import { ArrowRight, Refresh } from '@element-plus/icons-vue';import { compareTasks, getTasks } from '@/api/task';import { getProjects } from '@/api/log'
const router=useRouter(),loading=ref(false),error=ref(''),project=ref(''),projects=ref([]),tasks=ref([]),rows=ref([]),dialog=ref(false),selected=ref(null);const groups=[{key:'new',label:'新增异常'},{key:'increased',label:'异常增多'},{key:'persistent',label:'持续存在'},{key:'decreased',label:'异常减少'}];const filtered=computed(()=>project.value?rows.value.filter(x=>x.project===project.value):rows.value);const open=row=>{selected.value=row;dialog.value=true};const count=v=>Array.isArray(v)?v.length:0
async function load(){loading.value=true;error.value='';try{const [result,list]=await Promise.all([getTasks({page:1,page_size:200,status:'completed',sort:'updated_at'}),getProjects().catch(()=>[])]);tasks.value=Array.isArray(result?.list)?result.list:[];projects.value=Array.isArray(list)&&list.length?list:[...new Set(tasks.value.map(x=>x.project_name).filter(Boolean))];const grouped=new Map();tasks.value.forEach(t=>{if(!t.version)return;const key=t.project_name||'未命名项目';const a=grouped.get(key)||[];a.push(t);grouped.set(key,a)});const pairs=[];grouped.forEach((a,p)=>{a.sort((x,y)=>new Date(x.updated_at)-new Date(y.updated_at));for(let i=1;i<a.length;i++)if(a[i].version!==a[i-1].version)pairs.push({project:p,current:a[i],baseline:a[i-1]})});rows.value=await Promise.all(pairs.slice(-24).map(async x=>{const raw=await compareTasks(x.baseline.task_id,x.current.task_id)||{};const details=Object.fromEntries(groups.map(g=>[g.key,Array.isArray(raw[g.key])?raw[g.key]:[]]));const row={project:x.project,currentTaskId:x.current.task_id,baselineVersion:x.baseline.version,currentVersion:x.current.version,details};row.newCount=count(details.new);row.increasedCount=count(details.increased);row.persistentCount=count(details.persistent);row.decreasedCount=count(details.decreased);row.attention=row.newCount+row.increasedCount>0;return row}))}catch(e){error.value=e?.response?.data?.message||e?.message||'版本对比加载失败'}finally{loading.value=false}}onMounted(load)
</script>
<style scoped>.page{height:100%;overflow:auto;padding:clamp(14px,2vw,26px);color:#e8edf2;background:linear-gradient(145deg,#14171b,#1b1f25 48%,#111418)}.head,.panel{border:1px solid rgba(255,255,255,.14);border-radius:12px;background:rgba(255,255,255,.07);box-shadow:0 14px 40px rgba(0,0,0,.2)}.head{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;padding:20px;margin-bottom:14px}.eyebrow{display:block;margin-bottom:6px;color:#67e8f9;font:600 10px ui-monospace,monospace;letter-spacing:.14em}.head h1{margin:0;color:#f5f7fa;font-size:23px}.head p{margin:6px 0 0;color:#aeb7c3;font-size:12px}.actions{display:flex;gap:8px}.panel{padding:18px}.mb{margin-bottom:14px}.list{display:grid;gap:8px}.row{display:flex;align-items:center;gap:16px;width:100%;padding:16px;border:1px solid rgba(255,255,255,.12);border-radius:9px;background:rgba(255,255,255,.04);color:#e8edf2;text-align:left;cursor:pointer}.row:hover{border-color:rgba(103,232,249,.5);background:rgba(6,182,212,.1)}.row>span{display:grid;min-width:190px;flex:1;gap:5px}.row small{display:flex;align-items:center;gap:4px;color:#aeb7c3;font:11px ui-monospace,monospace}.row b{color:#aeb7c3;font-size:12px}.row b.hot{color:#fb7185}.row i{display:flex;align-items:center;gap:4px;color:#67e8f9;font-size:11px;font-style:normal}.details{display:grid;gap:12px}.summary{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.summary span{padding:12px;border:1px solid rgba(255,255,255,.12);border-radius:7px;color:#aeb7c3}.summary b{display:block;color:#f5f7fa;font-size:22px}.details section{padding:12px;border:1px solid rgba(255,255,255,.12);border-radius:8px}.details section>strong{display:block;margin-bottom:8px}.details button{display:flex;justify-content:space-between;width:100%;padding:9px;border:0;border-top:1px solid rgba(255,255,255,.08);background:transparent;color:#dce4eb;text-align:left;cursor:pointer}.details button small{color:#929eaa}@media(max-width:600px){.head{align-items:stretch;flex-direction:column}.actions .el-select{flex:1}.row{align-items:flex-start;flex-direction:column;gap:8px}.summary{grid-template-columns:repeat(2,1fr)}}</style>
